import { promises as fs } from "fs";
import path from "path";
import type { SettlementFile } from "./geo";

// Every settlement in Eastern Province, Zambia — tens of thousands of villages and hamlets from
// OpenStreetMap, GeoNames and Google Open Buildings, generated by tools/settlements/fetch.py into
// public/settlements/eastern-province.json. This file is the server side (read the file once);
// the geometry (nearest, servedBy, catchments) lives in ./geo so the globe page can import it too.

export * from "./geo";

const REL = path.join("public", "settlements", "eastern-province.json");

// The dev server is not always started from the project folder (process.cwd() has been the
// Desktop), so look from the bundle's own folder upwards as well; SETTLEMENTS_FILE overrides.
async function locate(): Promise<string> {
  const candidates = [process.env.SETTLEMENTS_FILE, path.join(process.cwd(), REL)];
  let dir = typeof __dirname === "string" ? __dirname : process.cwd();
  for (let i = 0; i < 8; i++) {
    candidates.push(path.join(dir, REL));
    const up = path.dirname(dir);
    if (up === dir) break;
    dir = up;
  }
  for (const c of candidates) {
    if (!c) continue;
    try {
      await fs.access(c);
      return c;
    } catch {
      // next candidate
    }
  }
  throw new Error(`settlements file not found (looked for ${REL} from ${process.cwd()} and the server bundle); run tools/settlements/fetch.py`);
}

let cached: SettlementFile | null = null;

export async function load(): Promise<SettlementFile> {
  if (cached) return cached;
  const raw = await fs.readFile(await locate(), "utf8");
  cached = JSON.parse(raw) as SettlementFile;
  return cached;
}
